and strict-< relaxation yield the lexicographically smallest min-cost path?
Compare against brute-force enumeration of all simple paths."""
import heapq
import itertools
import random
import sys

sys.path.insert(0, "/var/tmp/space_data/space06/solverB/task017")


def brute(width, height, blocked, starts, goal, costs):
    def step_cost(p):
        return 1 if costs is None else costs[p[1]][p[0]]
    best = None  # (cost, path_tuple)
    for s in starts:
        # DFS all simple paths s -> goal
        stack = [([s], {s}, 0)]
        while stack:
            path, seen, g = stack.pop()
            cur = path[-1]
            if cur == goal:
                key = (g, tuple(path))
                if best is None or key < best:
                    best = key
                continue
            if best is not None and g >= best[0]:
                continue
            for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                np_ = (cur[0] + dx, cur[1] + dy)
                if not (0 <= np_[0] < width and 0 <= np_[1] < height):
                    continue
                if np_ in blocked or np_ in seen:
                    continue
                stack.append((path + [np_], seen | {np_}, g + step_cost(np_)))
    return best  # (cost, path) or None


def merged(width, height, blocked, starts, goal, costs):
    def h(p):
        return abs(p[0] - goal[0]) + abs(p[1] - goal[1])

    def step_cost(p):
        return 1 if costs is None else costs[p[1]][p[0]]
    heap = []
    for s in starts:
        heap.append((h(s), h(s), s[0], s[1], s))
    heapq.heapify(heap)
    came_from = {}
    g_score = {s: 0 for s in starts}
    closed = set()
    while heap:
        _, _, _, _, cur = heapq.heappop(heap)
        if cur in closed:
            continue
        closed.add(cur)
        if cur == goal:
            path = [cur]
            while path[-1] in came_from:
                path.append(came_from[path[-1]])
            path.reverse()
            return g_score[cur], tuple(path)
        for dx, dy in ((1, 0), (-1, 0), (0, 1), (0, -1)):
            np_ = (cur[0] + dx, cur[1] + dy)
            if not (0 <= np_[0] < width and 0 <= np_[1] < height):
                continue
            if np_ in blocked:
                continue
            ng = g_score[cur] + step_cost(np_)
            if ng < g_score.get(np_, float("inf")):
                g_score[np_] = ng
                came_from[np_] = cur
                heapq.heappush(heap, (ng + h(np_), h(np_), np_[0], np_[1], np_))
    return None


