"""Candidate plan_multi_start algorithm vs brute force.

Static: route-tree best-first (f,h,x,y,path) with per-coordinate close-prune.
Dynamic: route-tree best-first (f,h,x,y,t,path), no prune, best=(g,path).
"""
import heapq
import random

NEIGHBORS = ((1, 0), (-1, 0), (0, 1), (0, -1))

def search(width, height, obstacles, starts, goal, costs, frames=None):
    def heuristic(p):
        return abs(p[0] - goal[0]) + abs(p[1] - goal[1])
    def step_cost(p):
        return 1 if costs is None else costs[p[1]][p[0]]
    dynamic = frames is not None
    last_frame = len(frames) - 1 if dynamic else None
    def frame_cells(t):
        return frames[t] if t <= last_frame else frames[last_frame]
    open_heap = []
    for s in starts:
        h0 = heuristic(s)
        open_heap.append((h0, h0, s[0], s[1], 0, 0, (s,), frozenset((s,))))
    heapq.heapify(open_heap)
    closed = set()
    closed_count = 0
    expanded_nodes = []
    best_key = None
    while open_heap:
        if best_key is not None and open_heap[0][0] > best_key[0]:
            break
        entry = heapq.heappop(open_heap)
        f, hh, x, y, t, g, path, seen = entry
        if not dynamic and (x, y) in closed:
            continue
        closed_count += 1
        if not dynamic:
            closed.add((x, y))
        expanded_nodes.append((x, y, t) if dynamic else (x, y))
        if (x, y) == goal:
            if not dynamic:
                return {"path": list(path), "cost": g,
                        "expanded": closed_count,
                        "expanded_nodes": expanded_nodes}
            goal_key = (g, path)
            if best_key is None or goal_key < best_key:
                best_key = goal_key
            continue
        next_t = t + 1 if dynamic else 0
        frame = frame_cells(next_t) if dynamic else frozenset()
        for dx, dy in NEIGHBORS:
            nx, ny = x + dx, y + dy
            if not (0 <= nx < width and 0 <= ny < height):
                continue
            nxt = (nx, ny)
            if nxt in obstacles or nxt in frame or nxt in seen:
                continue
            new_g = g + step_cost(nxt)
            new_path = path + (nxt,)
