def brute(width, height, blocked, starts, goal, costs, frames=None):
    def step_cost(p):
        return 1 if costs is None else costs[p[1]][p[0]]
    dynamic = frames is not None
    last_frame = len(frames) - 1 if dynamic else None
    def frame_cells(t):
        return frames[t] if t <= last_frame else frames[last_frame]
    best = None
    for s in starts:
        stack = [([s], {s}, 0)]
        while stack:
            path, seen, g = stack.pop()
            cur = path[-1]
            t = len(path) - 1
            if cur == goal:
                key = (g, tuple(path))
                if best is None or key < best:
                    best = key
                continue
            if best is not None and g >= best[0]:
                continue
            nt = t + 1
            frame = frame_cells(nt) if dynamic else frozenset()
            for dx, dy in NEIGHBORS:
                np_ = (cur[0] + dx, cur[1] + dy)
                if not (0 <= np_[0] < width and 0 <= np_[1] < height):
                    continue
                if np_ in blocked or np_ in seen or np_ in frame:
                    continue
                stack.append((path + [np_], seen | {np_}, g + step_cost(np_)))
    return best  # (cost, path) or None


